{"file_path": "/Users/tongtao/apps/vc-daozhen/index.html", "new_string": "function resolveDay(v) {
  const map = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
  const now = new Date();
  const t = (v || "").trim().replace("星期", "周").replace("礼拜", "周");
  if (t === "今天") return map[now.getDay()];
  if (t === "明天") return map[(now.getDay() + 1) % 7];
  if (t === "后天") return map[(now.getDay() + 2) % 7];
  if (map.includes(t)) return t;
  let m = t.match(/(\d{4})[-/年.](\d{1,2})[-/月.](\d{1,2})/);
  if (m) return map[new Date(+m[1], +m[2] - 1, +m[3]).getDay()];
  m = t.match(/(\d{1,2})[-/月.](\d{1,2})/);
  if (m) return map[new Date(now.getFullYear(), +m[1] - 1, +m[2]).getDay()];
  return null;
}

