def normalize_day(raw: str, today: datetime | None = None) -> str | None:
    """把用户输入的日期规范化为一周中的某天(周X);无法识别返回 None。
    支持:今天 / 明天 / 后天 / 周X / 星期X / 礼拜X / 具体日期(2026-08-26、8月26日、8-26)"""
    t = (raw or "").strip().replace("星期", "周").replace("礼拜", "周")
    if not t:
        return None
    today = today or datetime.now()
    if t in ("今天",):
        return WEEK_CN[today.weekday()]
    if t == "明天":
        return WEEK_CN[(today.weekday() + 1) % 7]
    if t == "后天":
        return WEEK_CN[(today.weekday() + 2) % 7]
    if t in WEEK_CN:
        return t
    m = re.search(r"(\d{4})[-/年.](\d{1,2})[-/月.](\d{1,2})", t)
    if m:
        try:
            d = datetime(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            return WEEK_CN[d.weekday()]
        except ValueError:
            return None
    m = re.search(r"(\d{1,2})[-/月.](\d{1,2})", t)
    if m:
        try:
            d = datetime(today.year, int(m.group(1)), int(m.group(2)))
            return WEEK_CN[d.weekday()]
        except ValueError:
            return None
    return None


def resolve_choice(v: str, options: list) -> str | None:
    """把用户选择输入(编号 / 全名 / 唯一包含匹配)解析为 options 中的一项;无法解析返回 None。"""
    v = (v or "").strip()
    if not v:
        return None
    if v.isdigit():
        idx = int(v)
        return options[idx - 1] if 1 <= idx <= len(options) else None
    if v in options:
        return v
    hits = [o for o in options if v in o]
    return hits[0] if len(hits) == 1 else None


def pick(label: str, options: list, prompt: str = "选择:") -> str | None:
    """交互式编号选择;输入 q / 放弃 返回 None。"""
    print(label)
    for i, o in enumerate(options, 1):
        print(f"  {i}. {o}")
    while True:
        v = input(prompt).strip()
        if v in ("q", "Q", "放弃"):
            return None
        r = resolve_choice(v, options)
        if r is not None:
            return r
        print("无法识别,请输入列表中的编号或名称。")

