def known_patients(phone: str | None = None) -> list:
    """从预约历史中识别就诊人(姓名+手机号对),按登记次数降序;phone 非空时过滤。"""
    pairs: dict = {}
    for a in _load_appointments():
        p, ph = a.get("patient", ""), a.get("phone", "")
        if not p or not ph:
            continue
        key = (ph, p)
        if key not in pairs:
            pairs[key] = {"phone": ph, "patient": p, "count": 0, "last_dept": "", "last_at": ""}
        pairs[key]["count"] += 1
        pairs[key]["last_dept"] = a.get("dept", "")
        pairs[key]["last_at"] = a.get("created_at", "")
    out = sorted(pairs.values(), key=lambda x: -x["count"])
    if phone:
        out = [x for x in out if x["phone"] == phone]
    return out


