@contextlib.contextmanager
def _appt_lock():
    """预约数据读-改-写互斥锁(多线程 / 多进程安全;不支持 flock 的平台自动放行)。"""
    lock_path = APPT_FILE + ".lock"
    fh = open(lock_path, "a+")
    try:
        if fcntl is not None:
            try:
                fcntl.flock(fh, fcntl.LOCK_EX)
            except OSError:
                pass
        yield
    finally:
        if fcntl is not None:
            try:
                fcntl.flock(fh, fcntl.LOCK_UN)
            except OSError:
                pass
        fh.close()

